function toTitleCase(value) {
  return value
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function generateEmail(aridNo) {
  return `${aridNo.toLowerCase()}@biit.edu.pk`;
}

function parsePlayers(rawText) {
  const regex = /(\d+)\s+(20\d{2}-ARID-\d{4})\s+(.+?)(?=\s+\d+\s+20\d{2}-ARID-\d{4}\s+|$)/g;
  const records = [];
  let match;

  while ((match = regex.exec(rawText)) !== null) {
    const aridNo = match[2].toUpperCase();
    const name = toTitleCase(match[3]);

    records.push({
      name,
      arid_no: aridNo,
      age: 20,
      email: generateEmail(aridNo),
      password: 'Pass@123',
      role: 'player',
      gender: 'other',
    });
  }

  const dedupedByArid = new Map();
  for (const record of records) {
    if (!dedupedByArid.has(record.arid_no)) {
      dedupedByArid.set(record.arid_no, record);
    }
  }

  return {
    players: Array.from(dedupedByArid.values()),
    rawCount: records.length,
    uniqueCount: dedupedByArid.size,
    duplicateCount: records.length - dedupedByArid.size,
  };
}

async function run() {
  await connectDB();
  const { players, rawCount, uniqueCount, duplicateCount } = parsePlayers(RAW_PLAYERS);

  await User.deleteMany({});
  await User.insertMany(players);

  console.log(`Imported players successfully.`);
  console.log(`Parsed records: ${rawCount}`);
  console.log(`Inserted unique users: ${uniqueCount}`);
  console.log(`Skipped duplicate ARID entries: ${duplicateCount}`);
  process.exit(0);
}

run().catch((error) => {
  console.error('Player import failed:', error.message);
  process.exit(1);
});
